import threading
import time
import json
import win32com.client
import websocket

# Replace with your actual App ID and Access Token
APP_ID = ''"
ACCESS_TOKEN = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJhdWQiOlsiZDoxIiwiZDoyIiwieDowIiwieDoxIiwieDoyIl0sImF0X2hhc2giOiJnQUFBQUFCcVpEOFF5ZjYwdUktQmpxenJRWEVvLWthLVB4bVZuZFRndmpDUmZ1dXhTaWtsenFPMmtUb0JycFY1azhaYVRhTlVPak1YUXQwUzkyc2xsUkhGZjV0RG1kck8zckN4VFNCbnNub0RyQm1ZQUJWSWR5bz0iLCJkaXNwbGF5X25hbWy5155xMsk7kWae5RsvPoQL3R9YDX8'

# Path to your Excel file
EXCEL_FILE_PATH = r"F:\gemini option footprint\claude excel\Fyers_Ultimate_Terminal_V7.xlsx"

# Initialize global variables
XL = None
F = None
MARKET = {
    "connected": False,
    "ws": None
}
INDEX_MAP = {
    # Your index mapping
}
VIX_SYMBOL = "VIX"

# Lock for thread safety
import threading
STATE_LOCK = threading.Lock()

def bind_excel():
    global XL, F
    try:
        XL = win32com.client.Dispatch("Excel.Application")
        F = XL.Workbooks.Open(EXCEL_FILE_PATH)
        print("Excel file bound successfully.")
    except Exception as e:
        print("Failed to bind Excel:", e)

def save_and_close_excel():
    global F, XL
    try:
        F.Save()
        F.Close()
        XL.Quit()
        print("Excel saved and closed.")
    except Exception as e:
        print("Error closing Excel:", e)

def get_sheet(sheet_name):
    global F
    try:
        return F.Sheets(sheet_name)
    except Exception as e:
        print(f"Error accessing sheet {sheet_name}: {e}")
        return None

def update_option_chain(snap, index, tf, atm, step, vix):
    sheet = get_sheet("Option_Chain_Radar")
    if sheet:
        try:
            # Example: update cell B2
            sheet.Range("B2").Value = snap['price']
            print(f"Option Chain updated for {index}")
        except Exception as e:
            print("Error updating Option_Chain:", e)

def update_oi_dashboard(snap, index, tf):
    sheet = get_sheet("OI_Strike_Dashboard")
    if sheet:
        try:
            # Example: update cell C3
            sheet.Range("C3").Value = snap['price']
            print(f"OI Dashboard updated for {index}")
        except Exception as e:
            print("Error updating OI Dashboard:", e)

def update_market_structure():
    sheet = get_sheet("Market_Structure")
    if sheet:
        try:
            # Example: update some cell
            sheet.Range("A1").Value = "Updated"
            print("Market Structure updated.")
        except Exception as e:
            print("Error updating Market Structure:", e)

def update_live_candles():
    sheet = get_sheet("Live_Candle_Chart")
    if sheet:
        try:
            # Example: update some candle data
            sheet.Range("A2").Value = "New Candle Data"
            print("Live Candles updated.")
        except Exception as e:
            print("Error updating Live Candles:", e)

def update_footprint_data():
    sheet = get_sheet("Footprint_NIFTY")
    if sheet:
        try:
            sheet.Range("A1").Value = "Footprint Data"
            print("Footprint NIFTY updated.")
        except Exception as e:
            print("Error updating Footprint Data:", e)

def process_tick(msg):
    print("Processing tick for symbol:", msg.get("symbol"))
    # Parse data
    snap = msg.get("snapshot", {})
    index = msg.get("symbol", "N/A")
    tf = "5 min"  # or derive from data
    atm = 51000
    step = 100
    vix = 13.33

    # Call update functions
    update_option_chain(snap, index, tf, atm, step, vix)
    update_oi_dashboard(snap, index, tf)
    update_market_structure()
    update_live_candles()
    update_footprint_data()

def on_open(ws):
    with STATE_LOCK:
        MARKET["connected"] = True
    print("✅ [WS] Connected. Subscribing symbols...")
    symbols = [c["symbol"] for c in INDEX_MAP.values()] + [VIX_SYMBOL]
    ws.send(json.dumps({
        "symbol": symbols,
        "type": "subscribe"
    }))
    # Keep the connection alive
    threading.Thread(target=keep_running, args=(ws,)).start()

def keep_running(ws):
    while True:
        time.sleep(30)
        try:
            ws.send(json.dumps({"type": "keepalive"}))
        except:
            break

def on_message(ws, message):
    print("Received message:", message)
    try:
        msg = json.loads(message)
        if isinstance(msg, list):
            for t in msg:
                process_tick(t)
        else:
            process_tick(msg)
    except Exception as e:
        print("Error processing message:", e)

def on_error(ws, error):
    print("WebSocket Error:", error)

def on_close(ws, close_status_code, close_msg):
    with STATE_LOCK:
        MARKET["connected"] = False
    print("WebSocket closed.")

def start_websocket():
    ws_url = "wss://api.fyers.in/socket"  # Replace with actual WebSocket URL
    headers = [
	f"Authorization: Bearer {ACCESS_TOKEN}",
        f"App-Id: {APP_ID}"
    ]
    ws = websocket.WebSocketApp(ws_url,
				header=headers,
                                on_open=on_open,
                                on_message=on_message,
                                on_error=on_error,
                                on_close=on_close)
    MARKET["ws"] = ws
    ws.run_forever()

def main():
    # Bind to Excel
    bind_excel()

    # Start WebSocket in a thread
    threading.Thread(target=start_websocket).start()

    try:
        while True:
            time.sleep(10)
            # Periodically update other sheets if needed
            update_market_structure()
    except KeyboardInterrupt:
        print("Terminating...")
        save_and_close_excel()

if __name__ == "__main__":
    main()
